// Generated by nix/gen-shaders.py from Resources/shaders/*.glsl.
// Do not edit: change the GLSL and run `python3 nix/gen-shaders.py`.

/// The background shaders (GLSL ES 3.00 style), by file name without `.glsl`.
/// `common` is shared; the others each define `vec4 background()`.
public enum EmbeddedShaders {
    public static let sources: [String: String] = [
        "aurora": #"""
// aurora: two ribbons at the top and two at the bottom edge, blue over
// violet. No parameters. (The macOS and GTK renderers draw the aurora with
// their own copies of this; the web renderer uses this file.)
vec4 background() {
    // q.y is 0 at the top.
    vec2 q = vec2(uv.x, 1.0 - uv.y);
    float t = time;
    float topA = ribbon(q, 0.86, 0.060, t, 0.0);
    float topB = ribbon(q, 0.93, 0.035, t, 1.7);
    float botA = ribbon(q, 0.14, 0.060, t, 3.1);
    float botB = ribbon(q, 0.07, 0.035, t, 4.6);
    float hueTop = 0.58 + 0.10 * sin(q.x * 1.3 + t * 0.12);
    float hueBot = 0.78 + 0.10 * sin(q.x * 1.1 - t * 0.09);
    vec3 cTop = hsv2rgb(hueTop, 0.80, 1.0);
    vec3 cBot = hsv2rgb(hueBot, 0.75, 1.0);
    float aTop = topA * 0.55 + topB * 0.40;
    float aBot = botA * 0.55 + botB * 0.40;
    float alpha = min(aTop + aBot, 1.0);
    vec3 rgb = min(cTop * aTop + cBot * aBot, vec3(alpha));
    return vec4(rgb, alpha);
}

"""#,
        "common": #"""
// Shared by every background (GLSL ES 3.00 style; the host adds the
// `#version` line, `precision highp float;` where ES needs it, the output
// variable and `main`, which calls the body file's `vec4 background()`).
//
// Uniforms, the same on every renderer:
//   resolution  the render size in pixels (after backgroundResolution)
//   time        seconds; the renderer scales it (load runs faster when busy)
//   p           four parameters, per background (see its file)
//   c0..c3      colours, 0 to 1
// `uv` is 0 to 1 across the screen, y up. `background()` returns
// premultiplied alpha: no channel above alpha.
uniform vec2 resolution;
uniform float time;
uniform vec4 p;
uniform vec3 c0, c1, c2, c3;
in vec2 uv;

float hash(vec2 x) { x = fract(x * vec2(123.34, 456.21)); x += dot(x, x + 45.32); return fract(x.x * x.y); }

float vnoise(vec2 x) {
    vec2 i = floor(x), f = fract(x);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 x) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 5; i++) { v += a * vnoise(x); x = x * 2.02 + vec2(1.7, 9.2); a *= 0.5; }
    return v;
}

vec3 hsv2rgb(float h, float s, float v) {
    vec3 k = fract(vec3(h) + vec3(1.0, 2.0 / 3.0, 1.0 / 3.0));
    vec3 q = abs(k * 6.0 - 3.0) - 1.0;
    return v * mix(vec3(1.0), clamp(q, 0.0, 1.0), s);
}

// One ribbon of the aurora: a Gaussian around a baseline moved by four sines.
float ribbon(vec2 q, float baseline, float thickness, float t, float seed) {
    float wave =
        0.045 * sin(q.x * 2.3 + t * 0.35 + seed * 1.7) +
        0.028 * sin(q.x * 5.7 - t * 0.55 + seed * 2.9) +
        0.018 * sin(q.x * 11.3 + t * 0.85 + seed * 0.6) +
        0.011 * sin(q.x * 19.1 - t * 1.10 + seed * 4.4);
    float thickMod = thickness * (1.0 + 0.30 * sin(q.x * 1.4 + t * 0.20 + seed));
    float d = abs(q.y - (baseline + wave));
    return exp(-(d * d) / (thickMod * thickMod));
}

"""#,
        "flow": #"""
// flow: short comet trails carried along an invisible, slowly turning
// current. Each pixel follows the current forward a short way and adds up
// the dots it meets; the dots drift along the current and fade in and out
// like particles that live a few seconds. No parameters.
vec2 flowDir(vec2 s, float t) {
    float a = sin(s.x * 0.011 + t * 0.13) * 1.6 + cos(s.y * 0.013 - t * 0.09) * 1.6
            + sin((s.x + s.y) * 0.006 + t * 0.05) * 1.2;
    return vec2(cos(a), sin(a));
}

// The dots at `s` (a 625-unit-high space) in one half of the lifetime cycle:
// premultiplied colour and alpha.
vec4 dotsAt(vec2 s, float ph) {
    const float cycle = 3.2;
    float u = time / cycle + ph * 0.5;
    float tau = fract(u);
    float life = 1.0 - abs(2.0 * tau - 1.0);
    vec2 q = s - flowDir(s, time) * 130.0 * (tau - 0.5);
    float grid = 36.0;
    vec2 id = floor(q / grid);
    vec2 f = q / grid - id;
    float born = floor(u) * 17.3 + ph * 5.1;
    vec2 center = 0.2 + 0.6 * vec2(hash(id + born), hash(id.yx + born + 9.1));
    float d = length((f - center) * grid);
    float body = 1.0 - smoothstep(0.8, 1.6, d);
    float pick = hash(id + born + 4.4);
    vec3 col = pick < 0.333 ? vec3(0.478, 0.631, 0.969) : (pick < 0.667 ? vec3(0.729, 0.600, 0.969) : vec3(0.451, 0.839, 0.761));
    float alpha = pick < 0.333 ? 0.5 : (pick < 0.667 ? 0.46 : 0.4);
    float a = body * life * alpha * 0.7;
    return vec4(col * a, a);
}

vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 s = vec2(uv.x * asp, 1.0 - uv.y) * 625.0;
    vec4 acc = vec4(0.0);
    const int steps = 12;
    for (int i = 0; i < steps; i++) {
        float w = 1.0 - float(i) / float(steps);
        acc += (dotsAt(s, 0.0) + dotsAt(s, 1.0)) * (w * w);
        s += flowDir(s, time) * 2.0;
    }
    float a = min(acc.a, 1.0);
    return vec4(min(acc.rgb, vec3(a)), a);
}

"""#,
        "grain": #"""
// grain: film grain and darker corners.
vec4 background() {
    float n = hash(floor(gl_FragCoord.xy) + fract(time * 7.0) * vec2(113.0, 71.0)) - 0.5;
    float vig = smoothstep(0.30, 0.95, length((uv - 0.5) * vec2(1.25, 1.0)));
    float a = vig * 0.6 + abs(n) * 0.10;
    vec3 c = vec3(max(n, 0.0)) * 0.12;
    return vec4(c, a);
}

"""#,
        "load": #"""
// load: the aurora, thicker, warmer and brighter as the load rises.
// p.x is the load, 0 to 1. The renderer also runs `time` faster with it
// (0.5 + 3.2 * load times real time).
vec4 background() {
    vec2 q = vec2(uv.x, 1.0 - uv.y);
    float t = time, L = p.x;
    float th = 1.0 + 0.45 * L;
    float topA = ribbon(q, 0.86, 0.060 * th, t, 0.0);
    float topB = ribbon(q, 0.93, 0.035 * th, t, 1.7);
    float botA = ribbon(q, 0.14, 0.060 * th, t, 3.1);
    float botB = ribbon(q, 0.07, 0.035 * th, t, 4.6);
    float hueTop = 0.58 + 0.10 * sin(q.x * 1.3 + t * 0.12) + 0.42 * L;
    float hueBot = 0.78 + 0.10 * sin(q.x * 1.1 - t * 0.09) + 0.30 * L;
    vec3 cTop = hsv2rgb(hueTop, 0.80, 1.0);
    vec3 cBot = hsv2rgb(hueBot, 0.75, 1.0);
    float g = 0.7 + 0.6 * L;
    float aTop = (topA * 0.55 + topB * 0.40) * g;
    float aBot = (botA * 0.55 + botB * 0.40) * g;
    float alpha = min(aTop + aBot, 1.0);
    return vec4(min(cTop * aTop + cBot * aBot, vec3(alpha)), alpha);
}

"""#,
        "mesh": #"""
// mesh: four soft colour fields drifting over minutes (also artmesh).
// p.x is the opacity; c0..c3 the four colours.
vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 q = vec2(uv.x * asp, uv.y);
    float t = time * 0.06;
    vec2 q0 = vec2((0.25 + 0.18 * sin(t * 1.3)) * asp, 0.30 + 0.20 * cos(t * 1.1));
    vec2 q1 = vec2((0.75 + 0.15 * cos(t * 0.9)) * asp, 0.25 + 0.18 * sin(t * 1.7));
    vec2 q2 = vec2((0.70 + 0.20 * sin(t * 0.7 + 2.0)) * asp, 0.78 + 0.15 * cos(t * 1.3));
    vec2 q3 = vec2((0.22 + 0.16 * cos(t * 1.5 + 1.0)) * asp, 0.80 + 0.12 * sin(t * 0.8));
    float w0 = 1.0 / (pow(distance(q, q0), 2.2) + 0.02);
    float w1 = 1.0 / (pow(distance(q, q1), 2.2) + 0.02);
    float w2 = 1.0 / (pow(distance(q, q2), 2.2) + 0.02);
    float w3 = 1.0 / (pow(distance(q, q3), 2.2) + 0.02);
    vec3 c = (c0 * w0 + c1 * w1 + c2 * w2 + c3 * w3) / (w0 + w1 + w2 + w3);
    c += (fbm(q * 3.0 + t) - 0.5) * 0.04;
    float a = p.x;
    return vec4(c * a, a);
}

"""#,
        "plasma": #"""
// plasma: very low-contrast interference bands in blue and violet.
vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 q = vec2(uv.x * asp, uv.y);
    float t = time * 0.18;
    float v = sin(q.x * 3.0 + t) + sin(q.y * 4.0 - t * 1.3) + sin((q.x + q.y) * 2.5 + t * 0.7)
            + sin(length(q - vec2(0.5 * asp, 0.5)) * 6.0 - t);
    vec3 c = 0.5 + 0.5 * cos(6.2831 * (v * 0.12 + vec3(0.60, 0.68, 0.80)));
    c *= vec3(0.6, 0.5, 1.0);
    float a = 0.42 + 0.14 * sin(v);
    return vec4(c * a, a);
}

"""#,
        "rain": #"""
// rain: drops sliding down a pane over out-of-focus city lights.
vec3 lights(vec2 q, float asp, float sharp) {
    vec3 c = mix(vec3(0.015, 0.02, 0.05), vec3(0.06, 0.05, 0.11), q.y);
    for (int i = 0; i < 16; i++) {
        float fi = float(i);
        vec2 pos = vec2(hash(vec2(fi, 1.3)) * asp, 0.08 + hash(vec2(fi, 7.1)) * 0.6);
        pos.x += sin(time * 0.04 + fi) * 0.03;
        float r = (0.05 + 0.09 * hash(vec2(fi, 3.3))) * mix(1.0, 0.55, sharp);
        float dd = length(q - pos);
        vec3 lc = mix(vec3(1.0, 0.62, 0.32), vec3(0.45, 0.62, 1.0), step(0.55, hash(vec2(fi, 5.5))));
        c += lc * (1.0 - smoothstep(r * mix(0.2, 0.75, sharp), r, dd)) * (0.22 + 0.18 * hash(vec2(fi, 9.0)));
    }
    return c;
}

vec3 dropLayer(vec2 q, float cols, float sp, float seed) {
    float cw = 1.0 / cols;
    vec2 st = q / vec2(cw, 3.0 * cw);
    vec2 id = floor(st);
    vec2 cuv = fract(st);
    float n = hash(id + seed);
    if (n < 0.35) return vec3(0.0);
    float y = 1.0 - fract(time * sp * (0.6 + n) + n * 7.0);
    float x = 0.5 + 0.22 * sin(y * 9.0 + n * 6.28);
    vec2 rel = (cuv - vec2(x, y)) * vec2(1.0, 3.0);
    float r = 0.30 + 0.08 * n;
    float m = 1.0 - smoothstep(r * 0.75, r, length(rel));
    vec2 tr = vec2(cuv.x - x, (fract(cuv.y * 7.0) - 0.5) * 3.0 / 7.0);
    float above = smoothstep(y, y + 0.04, cuv.y) * (1.0 - smoothstep(y, y + 0.55, cuv.y));
    float tm = (1.0 - smoothstep(0.04, 0.065, length(tr))) * above;
    vec2 nrm = rel / r * m + tr * 6.0 * tm;
    return vec3(nrm, max(m, tm));
}

vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 q = vec2(uv.x * asp, uv.y);
    vec3 a = dropLayer(q, 9.0, 0.10, 0.0);
    vec3 b = dropLayer(q * 1.7 + 0.3, 15.0, 0.07, 3.1);
    vec2 off = a.xy * 0.05 + b.xy * 0.03;
    float m = max(a.z, b.z * 0.8);
    vec2 bead = fract(q * 40.0) - 0.5;
    vec2 bid = floor(q * 40.0);
    float bm = (1.0 - smoothstep(0.08, 0.14, length(bead))) * step(0.82, hash(bid + 2.0));
    vec3 fog = lights(q, asp, 0.0) * 0.6;
    vec3 clear = lights(q + off * 1.6, asp, 1.0) * 1.7 + vec3(0.03, 0.035, 0.05);
    vec3 c = mix(fog, clear, m);
    c += vec3(0.75, 0.82, 1.0) * m * (1.0 - m) * 0.55;
    c = mix(c, lights(q - bead * 0.02, asp, 1.0), bm * 0.7);
    c += vec3(0.6, 0.7, 0.9) * pow(max(0.0, -a.y), 3.0) * 0.08 * a.z;
    return vec4(c * 0.9, 0.9);
}

"""#,
        "sky": #"""
// sky: the sky colour, sun or moon, and stars at night, from the clock.
// p.xy the sun or moon's position (0 to 1, y up), p.z the stars' strength,
// p.w the brightness; c0 the colour overhead, c1 at the horizon, c2 the
// sun or moon.
vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 q = uv;
    vec3 c = mix(c1, c0, pow(q.y, 0.65));
    vec2 d = (q - p.xy) * vec2(asp, 1.0);
    float g = exp(-dot(d, d) * 14.0);
    c += c2 * g * 0.55;
    c = mix(c, c2, 1.0 - smoothstep(0.026, 0.032, length(d)));
    float s = hash(floor(gl_FragCoord.xy));
    float star = step(0.9965, s) * p.z * (0.55 + 0.45 * sin(time * 1.7 + s * 300.0)) * smoothstep(0.25, 0.8, q.y);
    c += star;
    c *= p.w;
    return vec4(c * 0.92, 0.92);
}

"""#,
        "stars": #"""
// stars: three depths of stars drifting sideways, the near ones faster,
// brighter and larger. A jittered grid per depth; no parameters.
vec4 starLayer(vec2 px, float z, float seed, float k) {
    // About 110 cells (87 stars) per depth.
    float cell = sqrt(resolution.x * resolution.y / 110.0);
    vec2 s = px + vec2(time * z * 0.006 * resolution.x, 0.0);
    vec2 id = floor(s / cell);
    vec2 f = s / cell - id;
    float h = hash(id + seed);
    float size = max(1.0, z * 1.6 * k);
    float margin = (size + 2.0) / cell;
    vec2 pos = margin + (1.0 - 2.0 * margin) * vec2(hash(id * 1.7 + seed + 3.1), hash(id + seed + 7.7));
    vec2 d = abs(f - pos) * cell;
    float body = 1.0 - smoothstep(size * 0.5 - 0.5, size * 0.5 + 0.5, length(d));
    float a = (0.25 + 0.6 * z) * (0.7 + 0.3 * sin(time * 1.3 + h * 6.28)) * body * step(h, 0.8);
    vec3 col = z > 0.9 ? vec3(0.863, 0.902, 1.0) : vec3(0.667, 0.745, 1.0);
    return vec4(col * a, a);
}

vec4 background() {
    vec2 px = uv * resolution;
    float k = resolution.x / 640.0;
    vec4 s = starLayer(px, 0.25, 0.0, k) + starLayer(px, 0.5, 11.0, k) + starLayer(px, 1.0, 23.0, k);
    float a = min(s.a, 1.0);
    return vec4(min(s.rgb, vec3(a)), a);
}

"""#,
        "topo": #"""
// topo: contour lines of a slowly shifting terrain, every fifth brighter.
vec4 background() {
    float asp = resolution.x / resolution.y;
    vec2 q = vec2(uv.x * asp, uv.y);
    float t = time * 0.025;
    float n = fbm(q * 1.6 + vec2(t, t * 0.6)) + 0.25 * fbm(q * 3.1 - vec2(t * 0.7, 0.0));
    float v = n * 16.0;
    float d = abs(fract(v + 0.5) - 0.5);
    float w = fwidth(v);
    float line = 1.0 - smoothstep(0.0, w * 1.3, d);
    float idx = floor(v + 0.5);
    float major = 1.0 - step(0.5, mod(idx, 5.0));
    vec3 c = mix(vec3(0.49, 0.81, 1.0), vec3(0.73, 0.6, 0.97), smoothstep(0.35, 0.8, n));
    float a = line * mix(0.09, 0.24, major) + smoothstep(0.4, 0.9, n) * 0.04;
    return vec4(c * a, a);
}

"""#,
        "weather": #"""
// weather: rain, snow, a storm or a clear-day haze.
// p.x is the condition: 0 clear, 1 rain, 2 snow, 3 storm.
// Particles live in a canvas-space grid (y down, in render pixels).

// Round particles drifting vertically at `fall` pixels a second (negative:
// rising), swaying a little. About `count` of them.
vec4 driftLayer(vec2 px, float count, float seed, float fall, float radius, float alpha, float sway, vec3 col) {
    float cell = sqrt(resolution.x * resolution.y / count);
    vec2 s = px - vec2(0.0, time * fall);
    vec2 id = floor(s / cell);
    vec2 f = s / cell - id;
    float h = hash(id + seed);
    float x = 0.5 + (hash(id * 1.3 + seed + 2.0) - 0.5) * 0.4 + sway * sin(time * 0.8 + h * 6.28);
    float y = 0.25 + 0.5 * hash(id + seed + 5.0);
    float d = length((f - vec2(x, y)) * cell);
    float body = 1.0 - smoothstep(radius - 0.5, radius + 0.5, d);
    float a = alpha * body * step(h, 0.9);
    return vec4(col * a, a);
}

// Streaks falling with a slant: vertical segments in a sheared space.
vec4 rainLayer(vec2 px, float z, float seed, float cols, float speed, float slant, float length_, float k) {
    float w = resolution.x, h = resolution.y;
    float m = slant * 0.4 * w / h;
    float cw = w / cols;
    float rowH = h * 0.5;
    float sx = px.x - m * px.y;
    float yy = px.y - time * speed * z * h;
    vec2 id = floor(vec2(sx / cw, yy / rowH));
    float ly = yy - id.y * rowH;
    float len = length_ * z * h;
    float head = len + 2.0 + (rowH - len - 4.0) * hash(id + seed + 1.0);
    float x = (id.x + 0.15 + 0.7 * hash(id + seed)) * cw;
    float dx = (sx - x) / sqrt(1.0 + m * m);
    float dy = max(max(head - len - ly, ly - head), 0.0);
    float half_ = max(1.0, k) * 0.5;
    float body = 1.0 - smoothstep(half_, half_ + 1.0, length(vec2(dx, dy)));
    float a = (0.12 + 0.3 * z) * body;
    return vec4(vec3(0.667, 0.784, 1.0) * a, a);
}

vec4 background() {
    float mode = p.x;
    float k = resolution.x / 640.0;
    float w = resolution.x, h = resolution.y;
    vec2 px = vec2(uv.x, 1.0 - uv.y) * resolution;
    vec4 acc = vec4(0.0);
    if (mode < 0.5) {
        float d = length(px - vec2(0.8 * w, 0.1 * h)) / (0.5 * w);
        float g = 0.22 * clamp(1.0 - d, 0.0, 1.0);
        acc += vec4(vec3(1.0, 0.824, 0.549) * g, g);
        vec3 col = vec3(1.0, 0.925, 0.784);
        acc += driftLayer(px, 14.0, 0.0, -0.0018 * h, 1.4 * k * 0.45 + 0.5, 0.26, 0.2, col);
        acc += driftLayer(px, 13.0, 9.0, -0.0028 * h, 1.4 * k * 0.7 + 0.5, 0.33, 0.2, col);
        acc += driftLayer(px, 13.0, 19.0, -0.004 * h, 1.4 * k + 0.5, 0.4, 0.2, col);
    } else if (mode < 1.5 || mode > 2.5) {
        bool storm = mode > 2.5;
        float cols = storm ? 70.0 : 43.0;
        float speed = storm ? 1.5 : 1.0;
        float slant = storm ? 0.18 : 0.08;
        float len = storm ? 0.05 : 0.035;
        acc += rainLayer(px, 0.5, 0.0, cols, speed, slant, len, k);
        acc += rainLayer(px, 0.75, 13.0, cols, speed, slant, len, k);
        acc += rainLayer(px, 1.0, 29.0, cols, speed, slant, len, k);
        if (storm) {
            float epoch = floor(time / 4.0);
            float strike = epoch * 4.0 + hash(vec2(epoch, 3.3)) * 3.5;
            float flash = time >= strike ? clamp(1.0 - (time - strike) * 3.5, 0.0, 1.0) : 0.0;
            float fa = flash * 0.22;
            acc += vec4(vec3(0.784, 0.843, 1.0) * fa, fa);
        }
    } else {
        vec3 col = vec3(0.922, 0.941, 1.0);
        acc += driftLayer(px, 73.0, 0.0, 0.035 * 0.45 * h, (1.0 + 2.2 * 0.45) * k, 0.25 + 0.55 * 0.45, 0.12, col);
        acc += driftLayer(px, 73.0, 9.0, 0.035 * 0.7 * h, (1.0 + 2.2 * 0.7) * k, 0.25 + 0.55 * 0.7, 0.12, col);
        acc += driftLayer(px, 73.0, 19.0, 0.035 * h, (1.0 + 2.2) * k, 0.25 + 0.55, 0.12, col);
    }
    float a = min(acc.a, 1.0);
    return vec4(min(acc.rgb, vec3(a)), a);
}

